Boolean out_q_exec( void *dummy , Out_Q out_q ) //--- return 0 : when queue is sleeping (no out object in queue)
{                                               //           1 : when queue is busy
    Boolean q_is_busy = FALSE; 

	Fifo_Node *curr , *temp ;
	
	for( curr = out_q->fifo_exec->rhs ; curr != out_q->fifo_exec ; curr = curr->rhs )
	{
		if( ((Out_Q_Node*)curr)->req_done || out_exec( NULL , ((Out_Q_Node*)curr)->out ) )
		{
			if( ((Out_Q_Node*)curr)->req_done  )
			{	
				if( ((Out_Q_Node*)curr)->do_reset )
				{
					out_exec_stop( ((Out_Q_Node*)curr)->out , FALSE ) ; 
				};
				
				((Out_Q_Node*)curr)->req_done = FALSE ; 
			};				
						
			temp = curr->rhs ; 
			
			fifo_unlink( curr ) ; 

			fifo_insert( out_q->fifo_free , curr ) ; 
			
			curr = temp ;             
		}
		
		q_is_busy = TRUE ;		
	}	
	
	return q_is_busy ; 
}
        
